async function finishWorkout(early=false){if(!state.active)return;const s=state.active;s.finishedAt=new Date().toISOString();s.notes=[s.notes,early?'Session ended early.':''].filter(Boolean).join(' ');delete s.currentIndex;delete s.halted;delete s.restUntil;delete s.readinessDecision;const toStore={...s,exercises:s.exercises.filter(e=>e.sets.length||e.skipReason).map(e=>({warmups:(e.warmups||[]).filter(x=>x.done).map(({weight,reps})=>({weight,reps})),exerciseId:e.id,machineId:e.machineId,plannedSets:e.plannedSets,sets:e.sets,notes:[e.skipReason?`Skipped: ${e.skipReason}`:'',e.notes||''].filter(Boolean).join(' '),formIssue:e.sets.some(x=>x.formIssue),dizziness:e.sets.some(x=>x.dizziness),pain:e.sets.some(x=>x.pain)}))};if(buildSummary(toStore).sets===0){if(!await askConfirm('No completed sets were logged. Discard this empty session?'))return;state.active=null;restUntil=0;view='overview';persist();render();return}state.history.push(toStore);state.active=null;selectedPlan=null;restUntil=0;view='overview';persist();render();const summary=buildSummary(toStore);toast(`Saved: ${summary.sets} actual sets across ${summary.exercises} exercises.`)}
