// In-app confirm / text prompts (the browser's own pop-ups are blocked inside embedded previews and look out of place).
function dialogRoot(){let r=document.getElementById('confirm-root');if(!r){r=document.createElement('div');r.id='confirm-root';document.body.append(r)}return r}
function askConfirm(message){return new Promise(res=>{const root=dialogRoot();const danger=/delete|discard|reset|remove|cancel this|clear|replace/i.test(message);const okLabel=!danger?'Yes':/cancel this/i.test(message)?'Yes, cancel':/replace/i.test(message)?'Yes, replace':'Yes, delete';
 root.innerHTML=`<div class="modal-backdrop sheet confirm-layer"><div class="modal confirm-box" role="alertdialog" aria-modal="true" aria-labelledby="cf-msg"><p id="cf-msg" class="cf-msg">${esc(message)}</p><div class="modal-actions"><button type="button" class="btn btn-subtle" data-cf="0">Go back</button><button type="button" class="btn ${danger?'btn-danger-solid':'btn-dark'}" data-cf="1">${okLabel}</button></div></div></div>`;
 const done=v=>{root.innerHTML='';res(v)};root.querySelector('[data-cf="1"]').onclick=()=>done(true);root.querySelector('[data-cf="0"]').onclick=()=>done(false);root.firstElementChild.onclick=e=>{if(e.target===e.currentTarget)done(false)};root.querySelector('[data-cf="1"]').focus()})}
function askText(message,value=''){return new Promise(res=>{const root=dialogRoot();
 root.innerHTML=`<div class="modal-backdrop sheet confirm-layer"><form class="modal confirm-box" role="dialog" aria-modal="true" aria-labelledby="cf-msg"><label id="cf-msg" class="cf-msg" for="cf-input">${esc(message)}</label><div class="form-field"><input id="cf-input" autocomplete="off" value="${esc(value)}"/></div><div class="modal-actions"><button type="button" class="btn btn-subtle" data-cf="0">Go back</button><button type="submit" class="btn btn-dark">OK</button></div></form></div>`;
 const done=v=>{root.innerHTML='';res(v)};const f=root.querySelector('form');f.onsubmit=e=>{e.preventDefault();e.stopPropagation();done(root.querySelector('#cf-input').value)};root.querySelector('[data-cf="0"]').onclick=()=>done(null);root.firstElementChild.onclick=e=>{if(e.target===e.currentTarget)done(null)};setTimeout(()=>root.querySelector('#cf-input')?.focus(),30)})}
// Draggable bar meters for the readiness check (native range input under a row of bars).
const meter=(id,name,min,max,step,val,label)=>{const n=Math.round((max-min)/step)+1;return `<div class="meter" data-kind="${id}"><div class="meter-top"><label class="meter-label" for="${id}">${label}</label><output id="${id}-out" for="${id}"></output></div><div class="meter-track"><div class="meter-bars">${'<i></i>'.repeat(n)}</div><input type="range" id="${id}" ${name?`name="${name}"`:''} min="${min}" max="${max}" step="${step}" value="${val}"/></div></div>`};
function updateMeter(inp){const m=inp.closest('.meter');if(!m)return;const v=Number(inp.value),min=Number(inp.min),step=Number(inp.step),idx=Math.round((v-min)/step),bars=m.querySelectorAll('.meter-bars i');const kind=m.dataset.kind;let text='',tone='good';
 if(kind==='energy'){text=`${v}/10 · ${v<=2?'Very low':v<=4?'Low':v<=6?'OK':v<=8?'Good':'Great'}`;tone=v<=2?'bad':v<=5?'warn':'good'}
 else if(kind==='sleep'){text=`${v} h`;tone=v<6?'warn':'good'}
 else if(kind==='soreness-r'){const k=['none','mild','high'][v];text=['None','Mild','High'][v];tone=v===2?'bad':v===1?'warn':'good';const h=document.getElementById('soreness');if(h)h.value=k}
 bars.forEach((b,i)=>b.classList.toggle('on',i<=idx));m.dataset.tone=tone;const out=m.querySelector('output');if(out)out.textContent=text}
